    "featureId": "owner-updates",
    "slug": "owner-updates",
    "title": "Reviewing and Publishing Owner Updates",
    "summary": "Turn approved project records into polished owner updates and shareable reports.",
    "contextSummary": "An Owner Update is a client-facing publication. Review its wording, reporting period, photos, links, and audience before publishing or sharing it.",
    "category": "Client Communication",
    "tags": [
      "owner updates",
      "clients",
      "email",
      "printing",
      "publishing",
      "reports"
    ],
    "audiences": [
      "staff"
    ],
